import Head from 'next/head'
import Link from 'next/link'
import { useState, useEffect } from 'react'

export default function Layout({ children, title = 'Helios Mission Control' }) {
  const [sidebarOpen, setSidebarOpen] = useState(false)
  const [currentTime, setCurrentTime] = useState('')

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date()
      setCurrentTime(now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }))
    }, 1000)
    return () => clearInterval(timer)
  }, [])

  const navItems = {
    'Mission Control': [
      { name: '🏠 Dashboard', href: '/', icon: '🏠' },
      { name: '🏛️ Hierarchy', href: '/hierarchy', icon: '🏛️' },
      { name: '📱 Social Media', href: '/social-posts', icon: '📱' },
    ],
    'Helios Skills': [
      { name: '📖 Soul', href: '/skills/soul', icon: '📖' },
      { name: '💓 Heartbeat', href: '/skills/heartbeat', icon: '💓' },
      { name: '🧠 Memory', href: '/skills/memory', icon: '🧠' },
      { name: '🛠️ All Skills', href: '/skills', icon: '🛠️' },
    ],
    'Data & Tools': [
      { name: '🛢️ Carbon Cut', href: 'https://orphan-well-dashboard.vercel.app', icon: '🛢️', external: true },
      { name: '📁 Workspace', href: '/workspace', icon: '📁' },
      { name: '⚙️ Settings', href: '/settings', icon: '⚙️' },
    ],
  }

  return (
    <>
      <Head>
        <title>{title}</title>
        <meta name="viewport" content="width=device-width, initial-scale=1" />
      </Head>

      <div className="min-h-screen bg-slate-900 flex">
        {/* Sidebar */}
        <aside className={`
          fixed md:relative z-50
          ${sidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
          w-64 bg-slate-800 border-r border-slate-700
          h-screen overflow-y-auto
          transition-transform duration-300 ease-in-out
        `}>
          {/* Logo */}
          <div className="p-4 border-b border-slate-700 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="text-2xl">🤖</span>
              <div>
                <p className="font-bold text-white">Helios</p>
                <p className="text-xs text-green-400">● Online</p>
              </div>
            </div>
            <button 
              onClick={() => setSidebarOpen(false)}
              className="md:hidden text-slate-400 hover:text-white"
            >
              ✕
            </button>
          </div>

          {/* Time */}
          <div className="p-4 border-b border-slate-700">
            <p className="text-slate-400 text-sm">{currentTime || '--:--'} MST</p>
          </div>

          {/* Navigation */}
          <nav className="p-4 space-y-6">
            {Object.entries(navItems).map(([category, items]) => (
              <div key={category}>
                <h3 className="text-slate-500 text-xs uppercase tracking-wider mb-2">{category}</h3>
                <ul className="space-y-1">
                  {items.map((item, idx) => (
                    <li key={idx}>
                      {item.external ? (
                        <a 
                          href={item.href} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="flex items-center gap-3 px-3 py-2 text-slate-300 hover:bg-slate-700 rounded-lg transition-colors"
                        >
                          <span>{item.icon}</span>
                          <span className="flex-1">{item.name}</span>
                          <span className="text-slate-500 text-xs">↗</span>
                        </a>
                      ) : (
                        <Link 
                          href={item.href}
                          className="flex items-center gap-3 px-3 py-2 text-slate-300 hover:bg-slate-700 rounded-lg transition-colors"
                        >
                          <span>{item.icon}</span>
                          <span className="flex-1">{item.name}</span>
                        </Link>
                      )}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </nav>
        </aside>

        {/* Mobile sidebar overlay */}
        {sidebarOpen && (
          <div 
            className="fixed inset-0 bg-black/50 z-40 md:hidden"
            onClick={() => setSidebarOpen(false)}
          />
        )}

        {/* Main Content */}
        <main className="flex-1 min-h-screen">
          {/* Mobile Header */}
          <header className="md:hidden bg-slate-800 border-b border-slate-700 p-4 flex items-center justify-between sticky top-0 z-30">
            <button 
              onClick={() => setSidebarOpen(true)}
              className="text-white p-2"
            >
              ☰
            </button>
            <div className="flex items-center gap-2">
              <span className="text-xl">🤖</span>
              <span className="font-bold">Helios</span>
            </div>
            <div className="w-10"></div>
          </header>

          {/* Page Content */}
          <div className="p-4 md:p-8">
            {children}
          </div>
        </main>
      </div>
    </>
  )
}
